interface MSMEData {
  companyName: string;
  companyType: string;
  industry: string;
  udyamRegistrationNumber?: string;
  udyogAadharNumber?: string;
  gstNumber: string;
  annualTurnover?: number;
  numberOfEmployees?: number;
  manufacturingUnits?: number;
}

/** API stores scale fields under `business`; normalize for dashboard display and charts. */
function normalizeMsmeProfileForDashboard(raw: Record<string, unknown> | null | undefined): MSMEData | null {
  if (!raw || typeof raw !== 'object') return null;
  const business = (raw.business as Record<string, unknown>) || {};
  const manufacturingProfile = (raw.manufacturingProfile as Record<string, unknown>) || {};
  const operations = (raw.operations as Record<string, unknown>) || {};
  const metrics = (operations.metrics as Record<string, unknown>) || {};

  const coalesceNumber = (...vals: unknown[]): number | undefined => {
    for (const v of vals) {
      if (typeof v === 'number' && !Number.isNaN(v)) return v;
    }
    return undefined;
  };

  return {
    companyName: String(raw.companyName ?? ''),
    companyType: String(raw.companyType ?? ''),
    industry: String(raw.industry ?? ''),
    udyamRegistrationNumber: raw.udyamRegistrationNumber as string | undefined,
    udyogAadharNumber: raw.udyogAadharNumber as string | undefined,
    gstNumber: String(raw.gstNumber ?? ''),
    annualTurnover: coalesceNumber(raw.annualTurnover, business.annualTurnover, metrics.annualTurnoverInr),
    numberOfEmployees: coalesceNumber(
      raw.numberOfEmployees,
      business.numberOfEmployees,
      manufacturingProfile.numberOfEmployees
    ),
    manufacturingUnits: coalesceNumber(raw.manufacturingUnits, business.manufacturingUnits),
  };
}

