import React, { useEffect, Suspense } from 'react';
import { Routes, Route, Navigate, useLocation } from 'react-router-dom';
import { Container, Box } from '@mui/material';
import Header from './components/Header';
import ErrorBoundary from './components/ErrorBoundary';
import MSMERegistration from './components/MSMERegistration';
import UserLogin from './components/UserLogin';
import Dashboard from './components/Dashboard';
import CarbonFootprint from './components/CarbonFootprint';
import CarbonSavings from './components/CarbonSavings';
import IncentivesScreen from './components/IncentivesScreen';
import ReportingScreen from './components/ReportingScreen';
import GreenLoans from './components/GreenLoans';
import EmissionsReductionTargets from './components/EmissionsReductionTargets';
import DocumentUpload from './components/DocumentUpload';
import DocumentManagement from './components/DocumentManagement';
import DataPrivacy from './components/DataPrivacy';
import CarbonTrading from './components/CarbonTrading';
import GIFTSchemes from './components/GIFTSchemes';
import GIFTApplications from './components/GIFTApplications';
import GIFTApplicationForm from './components/GIFTApplicationForm';
import ProtectedRoute from './components/ProtectedRoute';
import RequireMSME from './components/RequireMSME';
import RequireWorkflowPlanner from './components/RequireWorkflowPlanner';
import { RegistrationProvider } from './context/RegistrationContext';
import UserRegister from './components/UserRegister';
import ForgotPassword from './components/ForgotPassword';
import ResetPassword from './components/ResetPassword';
import MSMEList from './components/MSMEList';
import MSMEProfileSection from './components/MSMEProfileSection';
import OperationsPage from './components/OperationsPage';
import InformationPage from './components/InformationPage';
import { isAdminUserProfile } from './utils/authRole';
import {
  HelpCenterPage,
  PrivacyPolicyPage,
  SettingsPage,
  TermsOfServicePage,
} from './components/StaticPages';
import AdminLogin from './components/admin/AdminLogin';
import AdminDashboard from './components/admin/AdminDashboard';
import MSMEDetailView from './components/admin/MSMEDetailView';
import AdminRoute from './components/admin/AdminRoute';
import NotFoundPage from './components/NotFoundPage';
import NavigationRouteProgress from './components/NavigationRouteProgress';
import RouteLoadingGate from './components/RouteLoadingGate';
import { resolveDocumentTitle } from './utils/routePageMeta';

const CarbonForecastingGraph = React.lazy(() => import('./components/CarbonForecastingGraph'));

interface RouteWrapperProps {
  children: React.ReactElement;
}

const OnboardedRoute: React.FC<RouteWrapperProps> = ({ children }) => (
  <ProtectedRoute>
    <RequireMSME>
      <RequireWorkflowPlanner>{children}</RequireWorkflowPlanner>
    </RequireMSME>
  </ProtectedRoute>
);

const RequireMSMEProfile: React.FC<RouteWrapperProps> = ({ children }) => (
  <ProtectedRoute>
    <RequireMSME>{children}</RequireMSME>
  </ProtectedRoute>
);

const AdminProfileRoute: React.FC<RouteWrapperProps> = ({ children }) => {
  if (!isAdminUserProfile()) {
    return <Navigate to="/dashboard" replace />;
  }

  return <ProtectedRoute>{children}</ProtectedRoute>;
};

function AppRoutes() {
  const location = useLocation();
  const showSkipToMain = location.pathname !== '/dashboard';

  useEffect(() => {
    window.scrollTo({ top: 0, left: 0, behavior: 'auto' });
  }, [location.pathname, location.search]);

  useEffect(() => {
    document.title = resolveDocumentTitle(location.pathname || '/');
  }, [location.pathname]);

  return (
    <Box
      sx={{
        flexGrow: 1,
        minHeight: '100vh',
        backgroundColor: 'background.default',
      }}
    >
      <NavigationRouteProgress />
      {showSkipToMain && (
        <Box
          component="a"
          href="#main-content"
          sx={{
            position: 'absolute',
            left: 16,
            top: 12,
            zIndex: (theme) => theme.zIndex.appBar + 2,
            px: 1.5,
            py: 0.75,
            borderRadius: 1,
            bgcolor: 'background.paper',
            color: 'primary.main',
            fontWeight: 600,
            fontSize: '0.8125rem',
            textDecoration: 'none',
            boxShadow: 2,
            transform: 'translateY(-120%)',
            transition: 'transform 0.2s ease',
            '&:focus': {
              transform: 'translateY(0)',
              outline: '2px solid',
              outlineColor: 'primary.main',
              outlineOffset: 2,
            },
          }}
        >
          Skip to main content
        </Box>
      )}
      <Header />

          <Container sx={{ py: { xs: 2.5, md: 4 }, maxWidth: { lg: 1280, xl: 1400 } }}>
              <Box
                id="main-content"
                component="main"
                tabIndex={-1}
              sx={{
                pb: { xs: 2, md: 3 },
                outline: 'none',
              }}
            >
              <Suspense fallback={<RouteLoadingGate message="Loading page..." minHeight="40vh" />}>
              <Routes>
              <Route
                path="/msme-registration"
                element={(
                  <ProtectedRoute>
                    <MSMERegistration />
                  </ProtectedRoute>
                )}
              />
              <Route path="/" element={<UserLogin />} />
              <Route path="/login" element={<UserLogin />} />
              <Route path="/register" element={<UserRegister />} />
              <Route path="/forgot-password" element={<ForgotPassword />} />
              <Route path="/reset-password" element={<ResetPassword />} />
              <Route path="/privacy-policy" element={<PrivacyPolicyPage />} />
              <Route path="/terms-of-service" element={<TermsOfServicePage />} />
              <Route path="/help" element={<HelpCenterPage />} />
              <Route path="/admin" element={<Navigate to="/admin/login" replace />} />
              <Route path="/admin/login" element={<AdminLogin />} />
              <Route
                path="/admin/dashboard"
                element={(
                  <AdminRoute>
                    <AdminDashboard />
                  </AdminRoute>
                )}
              />
              <Route
                path="/admin/msme/:id"
                element={(
                  <AdminRoute>
                    <MSMEDetailView />
                  </AdminRoute>
                )}
              />
              <Route
                path="/dashboard"
                element={(
                  <OnboardedRoute>
                    <Dashboard />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/msme-list"
                element={(
                  <OnboardedRoute>
                    <MSMEList />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/msme-profile"
                element={(
                  <RequireMSMEProfile>
                    <MSMEProfileSection />
                  </RequireMSMEProfile>
                )}
              />
              <Route
                path="/msme-profile/workflow-planner"
                element={(
                  <RequireMSMEProfile>
                    <MSMEProfileSection />
                  </RequireMSMEProfile>
                )}
              />
              <Route
                path="/operations"
                element={(
                  <OnboardedRoute>
                    <OperationsPage />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/carbon-footprint"
                element={(
                  <OnboardedRoute>
                    <CarbonFootprint />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/carbon-credits"
                element={(
                  <OnboardedRoute>
                    <CarbonTrading />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/carbon-trading"
                element={(
                  <Navigate to="/carbon-credits" replace />
                )}
              />
              <Route
                path="/carbon-savings"
                element={(
                  <OnboardedRoute>
                    <CarbonSavings />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/gift-schemes"
                element={(
                  <OnboardedRoute>
                    <GIFTSchemes />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/gift-applications"
                element={(
                  <OnboardedRoute>
                    <GIFTApplications />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/gift-applications/new"
                element={(
                  <OnboardedRoute>
                    <GIFTApplicationForm />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/gift-applications/:schemeId/new"
                element={(
                  <OnboardedRoute>
                    <GIFTApplicationForm />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/gift-applications/:id/edit"
                element={(
                  <OnboardedRoute>
                    <GIFTApplicationForm />
                  </OnboardedRoute>
                )}
              />
              <Route path="/recommendations" element={<Navigate to="/carbon-footprint" replace />} />
              <Route
                path="/incentives"
                element={(
                  <OnboardedRoute>
                    <IncentivesScreen />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/reporting"
                element={(
                  <OnboardedRoute>
                    <ReportingScreen />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/multi-agent-management"
                element={(
                  <AdminProfileRoute>
                    <Navigate to="/dashboard" replace />
                  </AdminProfileRoute>
                )}
              />
              <Route
                path="/multi-agent-dashboard"
                element={(
                  <AdminProfileRoute>
                    <Navigate to="/dashboard" replace />
                  </AdminProfileRoute>
                )}
              />
              <Route
                path="/optimized-multi-agent-dashboard"
                element={(
                  <AdminProfileRoute>
                    <Navigate to="/dashboard" replace />
                  </AdminProfileRoute>
                )}
              />
              <Route
                path="/green-loans"
                element={(
                  <OnboardedRoute>
                    <GreenLoans />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/carbon-forecasting"
                element={(
                  <OnboardedRoute>
                    <CarbonForecastingGraph />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/emissions-reduction-targets"
                element={(
                  <OnboardedRoute>
                    <EmissionsReductionTargets />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/document-upload"
                element={(
                  <OnboardedRoute>
                    <DocumentUpload />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/data"
                element={(
                  <OnboardedRoute>
                    <DocumentManagement />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/document-management"
                element={(
                  <Navigate to="/data" replace />
                )}
              />
              <Route
                path="/data-privacy"
                element={(
                  <OnboardedRoute>
                    <DataPrivacy />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/manufacturing-workflow"
                element={(
                  <Navigate to="/operations" replace />
                )}
              />
              <Route
                path="/settings"
                element={(
                  <OnboardedRoute>
                    <SettingsPage />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/information"
                element={(
                  <OnboardedRoute>
                    <InformationPage />
                  </OnboardedRoute>
                )}
              />
                <Route path="*" element={<NotFoundPage />} />
              </Routes>
              </Suspense>
            </Box>
          </Container>
    </Box>
  );
}

function App() {
  return (
    <RegistrationProvider>
      <ErrorBoundary>
        <AppRoutes />
      </ErrorBoundary>
    </RegistrationProvider>
  );
}

export default App;
